// src/context/AppContext.js
import React, { createContext, useContext, useReducer, useEffect } from 'react';
import StorageManager from '../utils/StorageManager';

// Action types
const ActionTypes = {
  LOAD_DATA: 'LOAD_DATA',
  SET_LOADING: 'SET_LOADING',
  ADD_WORKOUT: 'ADD_WORKOUT',
  UPDATE_WORKOUT: 'UPDATE_WORKOUT',
  REMOVE_WORKOUT: 'REMOVE_WORKOUT',
  UPDATE_EXERCISE_HISTORY: 'UPDATE_EXERCISE_HISTORY',
  UPDATE_ONE_REP_MAX: 'UPDATE_ONE_REP_MAX',
  UPDATE_SETTINGS: 'UPDATE_SETTINGS',
  UPDATE_USER_STATS: 'UPDATE_USER_STATS',
  UPDATE_EXPERIENCE: 'UPDATE_EXPERIENCE',
  CLEAR_ALL_DATA: 'CLEAR_ALL_DATA',
  SET_ERROR: 'SET_ERROR',
  // New action types for templates and rest days
  ADD_TEMPLATE: 'ADD_TEMPLATE',
  UPDATE_TEMPLATE: 'UPDATE_TEMPLATE',
  REMOVE_TEMPLATE: 'REMOVE_TEMPLATE',
  ADD_REST_DAY: 'ADD_REST_DAY',
  REMOVE_REST_DAY: 'REMOVE_REST_DAY',
  UPDATE_REST_DAY: 'UPDATE_REST_DAY',
  // Body weight tracking
  ADD_BODY_WEIGHT: 'ADD_BODY_WEIGHT',
  UPDATE_BODY_WEIGHT: 'UPDATE_BODY_WEIGHT',
  REMOVE_BODY_WEIGHT: 'REMOVE_BODY_WEIGHT',
  // Demo mode
  SET_DEMO_MODE: 'SET_DEMO_MODE',
  LOAD_DEMO_DATA: 'LOAD_DEMO_DATA',
  // New gamification features
  COMPLETE_ACHIEVEMENT: 'COMPLETE_ACHIEVEMENT',
  COMPLETE_QUEST: 'COMPLETE_QUEST',
  COMPLETE_TEMPLATE: 'COMPLETE_TEMPLATE',
  UPDATE_ACHIEVEMENTS: 'UPDATE_ACHIEVEMENTS',
  UPDATE_QUESTS: 'UPDATE_QUESTS'
};

// WoW-style leveling curve (exponential growth)
const calculateLevelRequirement = (level) => {
  if (level <= 10) {
    return level * 100; // Early levels are easier
  } else if (level <= 30) {
    return Math.floor(1000 + (level - 10) * 150); // Moderate growth
  } else if (level <= 60) {
    return Math.floor(4000 + (level - 30) * 300); // Steeper growth
  } else {
    return Math.floor(13000 + (level - 60) * 500); // Very steep for high levels
  }
};

// Calculate total XP needed for a level
const calculateTotalXPForLevel = (level) => {
  let totalXP = 0;
  for (let i = 1; i <= level; i++) {
    totalXP += calculateLevelRequirement(i);
  }
  return totalXP;
};

// Initial state
const initialState = {
  loading: true,
  error: null,
  isDemo: false,
  workoutHistory: [],
  exerciseHistory: {},
  oneRepMaxes: {},
  settings: {
    units: 'lbs',
    notifications: true,
    darkMode: false,
    autoTimer: true,
    exportFormat: 'JSON',
    demoMode: false
  },
  userStats: {
    totalWorkouts: 0,
    totalDuration: 0,
    favoriteExercises: [],
    streaks: {
      current: 0,
      best: 0,
      lastWorkout: null
    },
    experience: 0,
    level: 1,
    totalExperience: 0,
    avgWorkoutsPerWeek: 0,
    avgRating: 0,
    // New gamification stats
    achievements: [],
    completedQuests: [],
    activeQuests: [],
    templateCompletions: {},
    muscleGroupMastery: {
      Chest: { level: 1, experience: 0, mastery: 0 },
      Back: { level: 1, experience: 0, mastery: 0 },
      Legs: { level: 1, experience: 0, mastery: 0 },
      Shoulders: { level: 1, experience: 0, mastery: 0 },
      Arms: { level: 1, experience: 0, mastery: 0 },
      Cardio: { level: 1, experience: 0, mastery: 0 }
    }
  },
  workoutTemplates: [],
  restDays: [],
  bodyWeights: []
};

// Reducer
const appReducer = (state, action) => {
  switch (action.type) {
    case ActionTypes.LOAD_DATA:
      return {
        ...state,
        ...action.payload,
        loading: false,
        error: null
      };

    case ActionTypes.SET_LOADING:
      return {
        ...state,
        loading: action.payload
      };

    case ActionTypes.SET_ERROR:
      return {
        ...state,
        error: action.payload,
        loading: false
      };

    case ActionTypes.ADD_WORKOUT:
      const newWorkoutHistory = [action.payload, ...state.workoutHistory];
      return {
        ...state,
        workoutHistory: newWorkoutHistory
      };

    case ActionTypes.UPDATE_WORKOUT:
      console.log('AppContext - UPDATE_WORKOUT reducer - action.payload:', action.payload);
      console.log('AppContext - UPDATE_WORKOUT reducer - action.payload.workoutDate:', action.payload.workoutDate);
      const updatedWorkoutHistory = state.workoutHistory.map(workout =>
        workout.id === action.payload.id ? action.payload : workout
      );
      console.log('AppContext - UPDATE_WORKOUT reducer - updatedWorkoutHistory length:', updatedWorkoutHistory.length);
      console.log('AppContext - UPDATE_WORKOUT reducer - updated workout in history:', updatedWorkoutHistory.find(w => w.id === action.payload.id));
      return {
        ...state,
        workoutHistory: updatedWorkoutHistory
      };

    case ActionTypes.REMOVE_WORKOUT:
      const filteredWorkoutHistory = state.workoutHistory.filter(workout =>
        workout.id !== action.payload
      );
      return {
        ...state,
        workoutHistory: filteredWorkoutHistory
      };

    case ActionTypes.UPDATE_EXERCISE_HISTORY:
      return {
        ...state,
        exerciseHistory: {
          ...state.exerciseHistory,
          ...action.payload
        }
      };

    case ActionTypes.UPDATE_ONE_REP_MAX:
      return {
        ...state,
        oneRepMaxes: {
          ...state.oneRepMaxes,
          ...action.payload
        }
      };

    case ActionTypes.UPDATE_SETTINGS:
      return {
        ...state,
        settings: {
          ...state.settings,
          ...action.payload
        }
      };

    case ActionTypes.UPDATE_USER_STATS:
      console.log('UPDATE_USER_STATS reducer - payload:', action.payload);
      const updatedUserStats = {
        ...state.userStats,
        ...action.payload
      };
      console.log('UPDATE_USER_STATS reducer - updated userStats:', updatedUserStats);
      return {
        ...state,
        userStats: updatedUserStats
      };

    case ActionTypes.UPDATE_EXPERIENCE:
      const { experienceGained, newLevel } = action.payload;
      const currentExp = state.userStats.experience + experienceGained;
      const currentLevel = newLevel || state.userStats.level;
      const totalExp = state.userStats.totalExperience + experienceGained;
      
      return {
        ...state,
        userStats: {
          ...state.userStats,
          experience: currentExp,
          level: currentLevel,
          totalExperience: totalExp
        }
      };

    case ActionTypes.ADD_TEMPLATE:
      return {
        ...state,
        workoutTemplates: [...state.workoutTemplates, action.payload]
      };

    case ActionTypes.UPDATE_TEMPLATE:
      return {
        ...state,
        workoutTemplates: state.workoutTemplates.map(template =>
          template.id === action.payload.id ? action.payload : template
        )
      };

    case ActionTypes.REMOVE_TEMPLATE:
      return {
        ...state,
        workoutTemplates: state.workoutTemplates.filter(template =>
          template.id !== action.payload
        )
      };

    case ActionTypes.ADD_REST_DAY:
      return {
        ...state,
        restDays: [...state.restDays, action.payload]
      };

    case ActionTypes.REMOVE_REST_DAY:
      return {
        ...state,
        restDays: state.restDays.filter(day =>
          day.date !== action.payload
        )
      };

    case ActionTypes.UPDATE_REST_DAY:
      return {
        ...state,
        restDays: state.restDays.map(day =>
          day.date === action.payload.date ? action.payload : day
        )
      };

    case ActionTypes.ADD_BODY_WEIGHT:
      const newBodyWeights = [...state.bodyWeights, action.payload].sort((a, b) => 
        new Date(b.date) - new Date(a.date)
      );
      return {
        ...state,
        bodyWeights: newBodyWeights
      };

    case ActionTypes.UPDATE_BODY_WEIGHT:
      return {
        ...state,
        bodyWeights: state.bodyWeights.map(entry =>
          entry.id === action.payload.id ? action.payload : entry
        )
      };

    case ActionTypes.REMOVE_BODY_WEIGHT:
      return {
        ...state,
        bodyWeights: state.bodyWeights.filter(entry =>
          entry.id !== action.payload
        )
      };

    case ActionTypes.CLEAR_ALL_DATA:
      return {
        ...initialState,
        loading: false
      };

    case ActionTypes.SET_DEMO_MODE:
      return {
        ...state,
        isDemo: action.payload.isDemo,
        settings: {
          ...state.settings,
          demoMode: action.payload.isDemo
        }
      };

    case ActionTypes.LOAD_DEMO_DATA:
      return {
        ...state,
        workoutHistory: action.payload.workoutHistory,
        exerciseHistory: action.payload.exerciseHistory,
        oneRepMaxes: action.payload.oneRepMaxes,
        userStats: action.payload.userStats,
        workoutTemplates: action.payload.workoutTemplates,
        restDays: action.payload.restDays,
        bodyWeights: action.payload.bodyWeights,
        isDemo: true,
        settings: {
          ...state.settings,
          demoMode: true
        }
      };

    case ActionTypes.COMPLETE_ACHIEVEMENT:
      return {
        ...state,
        userStats: {
          ...state.userStats,
          achievements: [...state.userStats.achievements, action.payload]
        }
      };

    case ActionTypes.COMPLETE_QUEST:
      return {
        ...state,
        userStats: {
          ...state.userStats,
          completedQuests: [...state.userStats.completedQuests, action.payload]
        }
      };

    case ActionTypes.COMPLETE_TEMPLATE:
      return {
        ...state,
        userStats: {
          ...state.userStats,
          templateCompletions: {
            ...state.userStats.templateCompletions,
            [action.payload]: (state.userStats.templateCompletions[action.payload] || 0) + 1
          }
        }
      };

    case ActionTypes.UPDATE_ACHIEVEMENTS:
      return {
        ...state,
        userStats: {
          ...state.userStats,
          achievements: action.payload
        }
      };

    case ActionTypes.UPDATE_QUESTS:
      return {
        ...state,
        userStats: {
          ...state.userStats,
          activeQuests: action.payload.activeQuests,
          completedQuests: action.payload.completedQuests
        }
      };

    default:
      return state;
  }
};

// Context
const AppContext = createContext();

// Provider component
export const AppProvider = ({ children }) => {
  const [state, dispatch] = useReducer(appReducer, initialState);

  // Load data on app start
  useEffect(() => {
    loadAllData();
  }, []);

  const loadAllData = async () => {
    dispatch({ type: ActionTypes.SET_LOADING, payload: true });
    
    try {
      const [
        workoutHistory,
        exerciseHistory,
        oneRepMaxes,
        settings,
        userStats,
        workoutTemplates,
        restDays,
        bodyWeights
      ] = await Promise.all([
        StorageManager.loadWorkoutHistory(),
        StorageManager.loadExerciseHistory(),
        StorageManager.loadOneRepMaxes(),
        StorageManager.loadSettings(),
        StorageManager.loadUserStats(),
        StorageManager.loadWorkoutTemplates(),
        StorageManager.loadRestDays(),
        StorageManager.loadBodyWeights()
      ]);

      // Ensure userStats has all required properties with proper defaults
      const validatedUserStats = {
        totalWorkouts: userStats?.totalWorkouts || 0,
        totalDuration: userStats?.totalDuration || 0,
        favoriteExercises: userStats?.favoriteExercises || [],
        streaks: {
          current: userStats?.streaks?.current || 0,
          best: userStats?.streaks?.best || 0,
          lastWorkout: userStats?.streaks?.lastWorkout || null
        },
        experience: userStats?.experience || 0,
        level: userStats?.level || 1,
        totalExperience: userStats?.totalExperience || 0,
        avgWorkoutsPerWeek: userStats?.avgWorkoutsPerWeek || 0,
        avgRating: userStats?.avgRating || 0,
        // New gamification stats
        achievements: userStats?.achievements || [],
        completedQuests: userStats?.completedQuests || [],
        activeQuests: userStats?.activeQuests || [],
        templateCompletions: userStats?.templateCompletions || {},
        muscleGroupMastery: userStats?.muscleGroupMastery || {
          Chest: { level: 1, experience: 0, mastery: 0 },
          Back: { level: 1, experience: 0, mastery: 0 },
          Legs: { level: 1, experience: 0, mastery: 0 },
          Shoulders: { level: 1, experience: 0, mastery: 0 },
          Arms: { level: 1, experience: 0, mastery: 0 },
          Cardio: { level: 1, experience: 0, mastery: 0 }
        }
      };

      console.log('loadAllData - loaded userStats:', validatedUserStats);

      dispatch({
        type: ActionTypes.LOAD_DATA,
        payload: {
          workoutHistory,
          exerciseHistory,
          oneRepMaxes,
          settings,
          userStats: validatedUserStats,
          workoutTemplates,
          restDays,
          bodyWeights
        }
      });

      // Check if demo mode is enabled and load demo data (only on startup)
      if (settings?.demoMode && !state.isDemo) {
        console.log('Demo mode enabled on startup, loading demo data...');
        dispatch({ 
          type: ActionTypes.SET_DEMO_MODE, 
          payload: { isDemo: true } 
        });
        await loadDemoData();
      }

      dispatch({ type: ActionTypes.SET_LOADING, payload: false });

      // Initialize base templates for new users
      await initializeBaseTemplates();
    } catch (error) {
      console.error('Error loading app data:', error);
      dispatch({ type: ActionTypes.SET_ERROR, payload: error.message });
      dispatch({ type: ActionTypes.SET_LOADING, payload: false });
    }
  };

  // Calculate average workouts per week
  const calculateAvgWorkoutsPerWeek = (workoutHistory) => {
    if (workoutHistory.length === 0) return 0;
    
    // Sort workouts by date
    const sortedWorkouts = [...workoutHistory].sort((a, b) => 
      new Date(a.workoutDate || a.startTime) - new Date(b.workoutDate || b.startTime)
    );
    
    const firstWorkoutDate = new Date(sortedWorkouts[0].workoutDate || sortedWorkouts[0].startTime);
    const lastWorkoutDate = new Date(sortedWorkouts[sortedWorkouts.length - 1].workoutDate || sortedWorkouts[sortedWorkouts.length - 1].startTime);
    
    // Calculate weeks between first and last workout
    const daysDiff = (lastWorkoutDate - firstWorkoutDate) / (1000 * 60 * 60 * 24);
    const weeksDiff = Math.max(1, Math.ceil(daysDiff / 7)); // At least 1 week
    
    return Math.round((workoutHistory.length / weeksDiff) * 10) / 10; // Round to 1 decimal
  };

  // Calculate average rating
  const calculateAvgRating = (workoutHistory) => {
    if (workoutHistory.length === 0) return 0;
    
    const totalRating = workoutHistory.reduce((sum, workout) => 
      sum + (workout.ratings?.workoutRating || 5), 0
    );
    
    return Math.round((totalRating / workoutHistory.length) * 10) / 10; // Round to 1 decimal
  };

  // WoW-style experience calculation function
  const calculateExperience = (workout) => {
    let experience = 0;
    
    // Base experience for completing a workout (scaled by level)
    const currentLevel = state.userStats.level || 1;
    const baseXP = Math.max(50, Math.floor(50 + (currentLevel - 1) * 5)); // XP scales with level
    experience += baseXP;
    
    // Bonus for workout duration (more time = more exp)
    if (workout.duration) {
      experience += Math.floor(workout.duration / 3); // 1 exp per 3 minutes (more generous)
    }
    
    // Bonus for number of exercises
    if (workout.exercises) {
      experience += workout.exercises.length * 15; // 15 exp per exercise
    }
    
    // Bonus for high workout rating
    if (workout.ratings && workout.ratings.workoutRating) {
      if (workout.ratings.workoutRating >= 9) experience += 50;
      else if (workout.ratings.workoutRating >= 8) experience += 30;
      else if (workout.ratings.workoutRating >= 7) experience += 20;
      else if (workout.ratings.workoutRating >= 6) experience += 10;
    }
    
    // Bonus for streak (exponential)
    if (state.userStats.streaks?.current > 0) {
      const streakBonus = Math.min(Math.pow(state.userStats.streaks.current, 1.5) * 10, 100);
      experience += streakBonus;
    }
    
    // Bonus for completing a template
    if (workout.templateId) {
      experience += 100; // Template completion bonus
    }
    
    console.log('calculateExperience - workout:', workout);
    console.log('calculateExperience - calculated experience:', experience);
    
    return experience;
  };

  // WoW-style level calculation function
  const calculateLevel = (totalExperience) => {
    let level = 1;
    let requiredXP = 0;
    
    while (totalExperience >= requiredXP) {
      requiredXP += calculateLevelRequirement(level);
      level++;
    }
    
    return Math.max(1, level - 1);
  };

  // Calculate XP progress to next level
  const calculateXPProgress = (totalExperience, currentLevel) => {
    const xpForCurrentLevel = calculateTotalXPForLevel(currentLevel - 1);
    const xpForNextLevel = calculateTotalXPForLevel(currentLevel);
    const xpInCurrentLevel = totalExperience - xpForCurrentLevel;
    const xpNeededForNextLevel = xpForNextLevel - xpForCurrentLevel;
    
    return {
      current: xpInCurrentLevel,
      required: xpNeededForNextLevel,
      progress: xpInCurrentLevel / xpNeededForNextLevel
    };
  };

  // Calculate muscle group mastery (much more difficult)
  const calculateMuscleGroupMastery = (muscleGroup, workoutHistory) => {
    let totalExperience = 0;
    let totalWorkouts = 0;
    let totalWeight = 0;
    let totalReps = 0;
    
    // Calculate experience from workout history
    workoutHistory.forEach(workout => {
      const exercisesInGroup = workout.exercises.filter(exercise => 
        exercise.name.toLowerCase().includes(muscleGroup.toLowerCase())
      );
      
      if (exercisesInGroup.length > 0) {
        totalWorkouts++;
        
        // Much more difficult XP calculation for muscle groups
        exercisesInGroup.forEach(exercise => {
          if (exercise.cardioData) {
            // Cardio experience (harder to gain)
            totalExperience += Math.floor(exercise.cardioData.duration / 10);
            totalExperience += Math.floor(exercise.cardioData.calories / 100);
          } else if (exercise.sets) {
            // Strength experience (much harder to gain)
            const totalWeight = exercise.sets.reduce((sum, set) => sum + (set.weight * set.reps), 0);
            totalWeight += totalWeight;
            totalReps += exercise.sets.reduce((sum, set) => sum + set.reps, 0);
            
            // XP based on total weight lifted (much more demanding)
            totalExperience += Math.floor(totalWeight / 500);
          }
        });
        
        // Bonus for good workout ratings
        if (workout.ratings?.workoutRating >= 8) {
          totalExperience += 10;
        }
      }
    });
    
    // Calculate mastery level (much more difficult progression)
    const masteryLevel = Math.floor(totalExperience / 200) + 1; // 200 XP per level instead of 100
    const masteryProgress = (totalExperience % 200) / 200;
    
    return {
      level: masteryLevel,
      experience: totalExperience,
      totalWorkouts,
      totalWeight,
      totalReps,
      mastery: Math.min(100, (masteryLevel - 1) * 10 + masteryProgress * 10)
    };
  };

