    } else if (totalWorkouts === 5) {
      newAchievements.push({ id: 'workout_5', xp: 200, title: 'Getting Started' });
    } else if (totalWorkouts === 25) {
      newAchievements.push({ id: 'workout_25', xp: 500, title: 'Dedicated Athlete' });
    } else if (totalWorkouts === 50) {
      newAchievements.push({ id: 'workout_50', xp: 1000, title: 'Fitness Enthusiast' });
    } else if (totalWorkouts === 100) {
      newAchievements.push({ id: 'workout_100', xp: 2500, title: 'Century Club' });
    }
    
    // Streak achievements
    const currentStreak = currentStats.streaks?.current + 1;
    if (currentStreak === 7) {
      newAchievements.push({ id: 'streak_7', xp: 300, title: 'Week Warrior' });
    } else if (currentStreak === 30) {
      newAchievements.push({ id: 'streak_30', xp: 1000, title: 'Month Master' });
    }
    
    // Rating achievements
    if (workout.ratings?.workoutRating >= 9) {
      newAchievements.push({ id: 'perfect_workout', xp: 150, title: 'Perfect Workout' });
    }
    
    // Template completion achievements
    if (workout.templateId) {
      const templateCompletions = (currentStats.templateCompletions?.[workout.templateId] || 0) + 1;
      if (templateCompletions === 1) {
        newAchievements.push({ id: `template_${workout.templateId}_first`, xp: 200, title: 'Template Master' });
      } else if (templateCompletions === 10) {
        newAchievements.push({ id: `template_${workout.templateId}_master`, xp: 500, title: 'Template Legend' });
      }
    }
    
    // Award XP for achievements
    let achievementXP = 0;
    newAchievements.forEach(achievement => {
      achievementXP += achievement.xp;
      dispatch({ type: ActionTypes.COMPLETE_ACHIEVEMENT, payload: achievement });
    });
    
    if (achievementXP > 0) {
      const newTotalExperience = currentStats.totalExperience + achievementXP;
      const newLevel = calculateLevel(newTotalExperience);
      
      const updatedStats = {
        ...currentStats,
        experience: currentStats.experience + achievementXP,
        level: newLevel,
