      };
      
      dispatch({ type: ActionTypes.UPDATE_USER_STATS, payload: updatedStats });
      await StorageManager.saveUserStats(updatedStats);
      
      console.log('Achievements awarded:', newAchievements, 'Total XP:', achievementXP);
    }
    
    return newAchievements;
  };

  // Quest system
  const generateDailyQuests = () => {
    const quests = [
      {
        id: 'daily_workout',
        title: 'Daily Grind',
        description: 'Complete a workout today',
        xp: 100,
        type: 'daily',
        progress: 0,
        maxProgress: 1
      },
      {
        id: 'daily_streak',
        title: 'Keep the Streak',
        description: 'Maintain your workout streak',
        xp: 50,
        type: 'daily',
        progress: 0,
        maxProgress: 1
      },
      {
        id: 'weekly_consistency',
        title: 'Weekly Warrior',
        description: 'Complete 4 workouts this week',
        xp: 300,
        type: 'weekly',
        progress: 0,
        maxProgress: 4
      }
    ];
    
    return quests;
  };

  const checkAndUpdateQuests = async (workout) => {
    const currentQuests = state.userStats.activeQuests || generateDailyQuests();
    const updatedQuests = currentQuests.map(quest => {
      let progress = quest.progress;
      
      switch (quest.id) {
        case 'daily_workout':
          progress = 1;
          break;
        case 'daily_streak':
          progress = state.userStats.streaks?.current > 0 ? 1 : 0;
          break;
        case 'weekly_consistency':
          // Count workouts this week
          const weekStart = new Date();
          weekStart.setDate(weekStart.getDate() - weekStart.getDay());
          const weekWorkouts = state.workoutHistory.filter(w => 
            new Date(w.startTime) >= weekStart
          ).length + 1;
          progress = Math.min(weekWorkouts, quest.maxProgress);
          break;
      }
      
      return { ...quest, progress };
    });
    
    // Check for completed quests
    const completedQuests = updatedQuests.filter(quest => quest.progress >= quest.maxProgress);
    let questXP = 0;
    
    completedQuests.forEach(quest => {
      questXP += quest.xp;
      dispatch({ type: ActionTypes.COMPLETE_QUEST, payload: quest });
    });
    
    if (questXP > 0) {
      const currentStats = state.userStats;
      const newTotalExperience = currentStats.totalExperience + questXP;
      const newLevel = calculateLevel(newTotalExperience);
      
      const updatedStats = {
        ...currentStats,
        experience: currentStats.experience + questXP,
        level: newLevel,
        totalExperience: newTotalExperience
      };
      
      dispatch({ type: ActionTypes.UPDATE_USER_STATS, payload: updatedStats });
      await StorageManager.saveUserStats(updatedStats);
      
      console.log('Quests completed:', completedQuests, 'Total XP:', questXP);
    }
    
    // Update active quests
    const activeQuests = updatedQuests.filter(quest => quest.progress < quest.maxProgress);
    dispatch({ type: ActionTypes.UPDATE_QUESTS, payload: { activeQuests, completedQuests } });
    
    return { completedQuests, questXP };
  };

  // Demo mode functions
  const setDemoMode = async (isDemo) => {
    try {
      console.log('setDemoMode called with:', isDemo);
      dispatch({ type: ActionTypes.SET_LOADING, payload: true });
      
      if (isDemo) {
        console.log('Enabling demo mode - backing up user data');
        // Backup current user data before switching to demo
        const backupSuccess = await StorageManager.backupUserData();
        console.log('Backup success:', backupSuccess);
        // Load demo data
        console.log('Loading demo data...');
        await loadDemoData();
        console.log('Demo data loaded successfully');
      } else {
        console.log('Disabling demo mode - restoring user data');
        // First update the settings to prevent reload loop
        const newSettings = { ...state.settings, demoMode: false };
        console.log('Saving settings first:', newSettings);
        await StorageManager.saveSettings(newSettings);
        
        // Update demo mode state
        dispatch({ 
          type: ActionTypes.SET_DEMO_MODE, 
          payload: { isDemo: false } 
        });
        
        // Restore user data from backup
        const restoreSuccess = await StorageManager.restoreUserData();
        console.log('Restore success:', restoreSuccess);
        
        // Reload the restored data (this should now work correctly)
        console.log('Reloading user data...');
        await loadAllData();
        console.log('User data reloaded successfully');
      }

      if (isDemo) {
        // Update demo mode setting for enabling demo mode
        console.log('Updating demo mode state...');
        dispatch({ 
          type: ActionTypes.SET_DEMO_MODE, 
          payload: { isDemo } 
        });
        
        // Save demo mode setting
        const newSettings = { ...state.settings, demoMode: isDemo };
        console.log('Saving settings:', newSettings);
        await StorageManager.saveSettings(newSettings);
      }
      
      dispatch({ type: ActionTypes.SET_LOADING, payload: false });
      console.log('Demo mode toggle completed successfully');
    } catch (error) {
      console.error('Error setting demo mode:', error);
      dispatch({ type: ActionTypes.SET_ERROR, payload: error.message });
      dispatch({ type: ActionTypes.SET_LOADING, payload: false });
    }
  };

  const loadDemoData = async () => {
    try {
      console.log('Resetting to dummy data...');
      // Reset to dummy data
      await StorageManager.resetToDummyData();
      console.log('Dummy data reset completed');
      
      // Load the dummy data
      console.log('Loading dummy data from storage...');
      const demoData = {
        workoutHistory: await StorageManager.loadWorkoutHistory(),
        exerciseHistory: await StorageManager.loadExerciseHistory(),
        oneRepMaxes: await StorageManager.loadOneRepMaxes(),
        userStats: await StorageManager.loadUserStats(),
        workoutTemplates: await StorageManager.loadWorkoutTemplates(),
        restDays: await StorageManager.loadRestDays(),
        bodyWeights: await StorageManager.loadBodyWeights()
      };
      
      console.log('Demo data loaded:', {
        workoutCount: demoData.workoutHistory.length,
        templatesCount: demoData.workoutTemplates.length,
        bodyWeightsCount: demoData.bodyWeights.length
      });
      
      dispatch({ 
        type: ActionTypes.LOAD_DEMO_DATA, 
        payload: demoData 
      });
      
    } catch (error) {
      console.error('Error loading demo data:', error);
      throw error;
    }
  };

  const value = {
    // State
    ...state,
    
    // Actions
    addWorkout,
    updateWorkout,
    removeWorkout,
    updateExerciseHistory,
    updateOneRepMax,
    updateSettings,
    exportData,
    importData,
    clearAllData,
    resetToDummyData,
    loadAllData,
    updateUserStats,
    // Template actions
    addTemplate,
    updateTemplate,
    removeTemplate,
    initializeBaseTemplates,
    // Rest day actions
    addRestDay,
    removeRestDay,
    updateRestDay,
    // Body weight actions
    addBodyWeight,
    updateBodyWeight,
    removeBodyWeight,
    // Demo mode actions
    setDemoMode,
    loadDemoData
  };

  return (
    <AppContext.Provider value={value}>
      {children}
    </AppContext.Provider>
  );
};

// Hook to use the context
export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) {
    throw new Error('useApp must be used within an AppProvider');
  }
  return context;
};

export default AppContext;
